const express = require('express');
const cors = require('cors');
const app = express();
const PORT = 3000;

app.use(cors());
app.use(express.json());

// UPI-accepting countries
const upiCountries = ['Singapore', 'UAE', 'Bhutan', 'Nepal', 'Malaysia'];

// Mock exchange rates
const rates = {
  GBP: 0.00956, USD: 0.01205, EUR: 0.01108,
  SGD: 0.01621, AED: 0.04425, JPY: 1.8340,
  CAD: 0.01641, AUD: 0.01852
};

// In-memory ledger
let transactions = [];
let totalVolume = 0;

// Payment endpoint
app.post('/pay', (req, res) => {
  const { sender, receiver, amount, currency, country } = req.body;
  const rate = rates[currency] || 0.01;
  const converted = (amount * rate).toFixed(2);
  const route = upiCountries.includes(country) ? 'UPI' : 'CBDC-BLOCKCHAIN';
  const ref = 'TXN-' + Date.now().toString().slice(-6);

  const txn = {
    ref, sender, receiver,
    amountINR: amount,
    converted, currency, country,
    route, status: 'Settled',
    timestamp: new Date().toLocaleTimeString()
  };

  transactions.unshift(txn);
  totalVolume += Number(amount);

  res.json({ success: true, ref, converted, currency, route });
});

// Dashboard data endpoint
app.get('/dashboard', (req, res) => {
  res.json({ transactions, totalVolume, count: transactions.length });
});

app.listen(PORT, () => {
  console.log('CBDC-UPI server running on http://localhost:3000');
});